 "content": "from collections import Counter


def transform(grid):
    """Erase the longest horizontal contiguous run of a non-background color."""
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    best = None
    for r, row in enumerate(grid):
        c = 0
        while c < len(row):
            color = row[c]
            end = c + 1
            while end < len(row) and row[end] == color:
                end += 1
            if color != background and (best is None or end - c > best[0]):
                best = (end - c, r, c, end)
            c = end
    if best is not None:
        _, r, start, end = best
        for c in range(start, end):
            out[r][c] = background
